import{_ as i,o as a,c as s,a0 as t}from"./chunks/framework.CShDTZbC.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/faq.md","filePath":"en/guide/faq.md"}'),n={name:"en/guide/faq.md"};function o(r,e,l,h,d,c){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="what-is-airlinesim-autobuy" tabindex="-1">What is AirlineSim Autobuy? <a class="header-anchor" href="#what-is-airlinesim-autobuy" aria-label="Permalink to &quot;What is AirlineSim Autobuy?&quot;">​</a></h3><p>AirlineSim Autobuy is a tool that monitors the AirlineSim used aircraft market and automatically purchases aircraft based on rules you define. It scans game servers at configurable intervals, evaluates listings against your rules, and optionally purchases matching aircraft.</p><h3 id="is-this-tool-allowed-by-the-game-s-terms-of-service" tabindex="-1">Is this tool allowed by the game&#39;s terms of service? <a class="header-anchor" href="#is-this-tool-allowed-by-the-game-s-terms-of-service" aria-label="Permalink to &quot;Is this tool allowed by the game&#39;s terms of service?&quot;">​</a></h3><p>AirlineSim Autobuy is designed for personal use and educational purposes. It interacts with the game through the same HTTP interface as a regular browser. However, automated tools may violate the game&#39;s terms of service. Use at your own risk. The developers recommend using reasonable polling intervals to avoid placing excessive load on game servers.</p><h3 id="does-the-tool-work-on-all-airlinesim-servers" tabindex="-1">Does the tool work on all AirlineSim servers? <a class="header-anchor" href="#does-the-tool-work-on-all-airlinesim-servers" aria-label="Permalink to &quot;Does the tool work on all AirlineSim servers?&quot;">​</a></h3><p>Yes, the tool supports any AirlineSim game server. Configure the server URL in the <code>servers</code> section of the configuration file. It works with both free and premium servers.</p><h3 id="do-i-need-programming-experience-to-use-this" tabindex="-1">Do I need programming experience to use this? <a class="header-anchor" href="#do-i-need-programming-experience-to-use-this" aria-label="Permalink to &quot;Do I need programming experience to use this?&quot;">​</a></h3><p>No. Basic configuration is done through a YAML file, and the web interface allows you to manage rules and settings without editing files directly. However, familiarity with editing text files and using a terminal is helpful.</p><h3 id="what-is-the-web-ui-built-with" tabindex="-1">What is the web UI built with? <a class="header-anchor" href="#what-is-the-web-ui-built-with" aria-label="Permalink to &quot;What is the web UI built with?&quot;">​</a></h3><p>The web UI is a Vue 3 single-page application built with Vite. It is embedded in the Go binary, so there are no additional dependencies to run the web interface.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><h3 id="how-do-i-set-up-multiple-accounts" tabindex="-1">How do I set up multiple accounts? <a class="header-anchor" href="#how-do-i-set-up-multiple-accounts" aria-label="Permalink to &quot;How do I set up multiple accounts?&quot;">​</a></h3><p>Use the <code>auths</code> list in the configuration file:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">auths</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">username</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;account1@example.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    password</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;password1&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    session_file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;session1.json&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">username</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;account2@example.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    password</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;password2&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    session_file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;session2.json&quot;</span></span></code></pre></div><p>Then reference the auth index in your rules using <code>auth_id</code>. See the <a href="/guide/configuration.html#auths">Configuration Guide</a> for details.</p><h3 id="can-i-monitor-multiple-servers-at-once" tabindex="-1">Can I monitor multiple servers at once? <a class="header-anchor" href="#can-i-monitor-multiple-servers-at-once" aria-label="Permalink to &quot;Can I monitor multiple servers at once?&quot;">​</a></h3><p>Yes. Add multiple entries to the <code>servers</code> list:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">servers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">free1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    base_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://free1.airlinesim.aero</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">free2</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    base_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://free2.airlinesim.aero</span></span></code></pre></div><p>The engine starts a separate monitoring loop for each server.</p><h3 id="how-do-i-change-the-polling-interval" tabindex="-1">How do I change the polling interval? <a class="header-anchor" href="#how-do-i-change-the-polling-interval" aria-label="Permalink to &quot;How do I change the polling interval?&quot;">​</a></h3><p>Edit the <code>monitor.interval</code> value in the configuration file. The value is in seconds. For example, <code>interval: 60</code> scans the market once per minute.</p><h3 id="what-does-the-jitter-setting-do" tabindex="-1">What does the jitter setting do? <a class="header-anchor" href="#what-does-the-jitter-setting-do" aria-label="Permalink to &quot;What does the jitter setting do?&quot;">​</a></h3><p>Jitter adds a random delay to each polling interval. This makes the request pattern less predictable, which helps avoid rate limiting. With <code>interval: 30</code> and <code>jitter: 10</code>, the actual delay is between 30 and 40 seconds.</p><h3 id="how-do-i-disable-the-web-ui" tabindex="-1">How do I disable the web UI? <a class="header-anchor" href="#how-do-i-disable-the-web-ui" aria-label="Permalink to &quot;How do I disable the web UI?&quot;">​</a></h3><p>Set <code>webui.enabled: false</code> in the configuration file:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">webui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><h3 id="how-do-i-make-the-web-ui-accessible-only-from-localhost" tabindex="-1">How do I make the web UI accessible only from localhost? <a class="header-anchor" href="#how-do-i-make-the-web-ui-accessible-only-from-localhost" aria-label="Permalink to &quot;How do I make the web UI accessible only from localhost?&quot;">​</a></h3><p>Set the bind address to <code>127.0.0.1</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">webui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">127.0.0.1</span></span></code></pre></div><h3 id="can-i-use-environment-variables-for-configuration" tabindex="-1">Can I use environment variables for configuration? <a class="header-anchor" href="#can-i-use-environment-variables-for-configuration" aria-label="Permalink to &quot;Can I use environment variables for configuration?&quot;">​</a></h3><p>Not currently. All configuration is read from the YAML file. This feature may be added in a future release.</p><h2 id="technical-issues" tabindex="-1">Technical Issues <a class="header-anchor" href="#technical-issues" aria-label="Permalink to &quot;Technical Issues&quot;">​</a></h2><h3 id="authentication-fails-with-login-failed" tabindex="-1">Authentication fails with &quot;login failed&quot; <a class="header-anchor" href="#authentication-fails-with-login-failed" aria-label="Permalink to &quot;Authentication fails with &quot;login failed&quot;&quot;">​</a></h3><p>Check the following:</p><ol><li><strong>Username and password</strong> -- Verify they are correct in the configuration file</li><li><strong>Server URL</strong> -- Ensure the <code>base_url</code> is correct (e.g., <code>https://free1.airlinesim.aero</code>)</li><li><strong>Network connectivity</strong> -- Ensure the machine running the tool can reach <code>sar.simulogics.games</code> and the game server</li><li><strong>Account status</strong> -- Ensure your AirlineSim account is active and not suspended</li><li><strong>Session file</strong> -- Delete the session file (default: <code>session.json</code>) and try again</li></ol><h3 id="the-engine-starts-but-finds-no-aircraft" tabindex="-1">The engine starts but finds no aircraft <a class="header-anchor" href="#the-engine-starts-but-finds-no-aircraft" aria-label="Permalink to &quot;The engine starts but finds no aircraft&quot;">​</a></h3><ol><li><strong>Check the market</strong> -- Log into the game manually and verify there are aircraft listed on the market</li><li><strong>Verify rules</strong> -- Ensure your rules are enabled and have correct match conditions</li><li><strong>Check logs</strong> -- Look for warnings or errors in the console output</li><li><strong>Session health</strong> -- The session may have expired. Check for &quot;session expired, re-authenticating&quot; messages</li></ol><h3 id="the-purchase-fails-with-bid-failed" tabindex="-1">The purchase fails with &quot;bid failed&quot; <a class="header-anchor" href="#the-purchase-fails-with-bid-failed" aria-label="Permalink to &quot;The purchase fails with &quot;bid failed&quot;&quot;">​</a></h3><ol><li><strong>Insufficient balance</strong> -- Check your account balance in the game</li><li><strong>Auction expired</strong> -- The auction may have ended before your bid was placed</li><li><strong>Already outbid</strong> -- Another player may have placed a higher bid</li><li><strong>Session expired</strong> -- The session may have expired between scanning and purchasing</li><li><strong>Check the aircraft URL</strong> -- The aircraft may have been removed from the market</li></ol><h3 id="the-web-ui-is-not-loading" tabindex="-1">The web UI is not loading <a class="header-anchor" href="#the-web-ui-is-not-loading" aria-label="Permalink to &quot;The web UI is not loading&quot;">​</a></h3><ol><li><strong>Check if the engine is running</strong> -- The web UI is embedded in the binary; if the application is running, the web UI should be available</li><li><strong>Verify the port</strong> -- Ensure the configured port is not in use by another application</li><li><strong>Check the bind address</strong> -- If bound to <code>127.0.0.1</code>, you can only access it from the same machine</li><li><strong>Firewall</strong> -- Ensure the port is not blocked by a firewall</li><li><strong>Check the logs</strong> -- Look for web UI startup errors</li></ol><h3 id="the-configuration-file-is-not-being-reloaded" tabindex="-1">The configuration file is not being reloaded <a class="header-anchor" href="#the-configuration-file-is-not-being-reloaded" aria-label="Permalink to &quot;The configuration file is not being reloaded&quot;">​</a></h3><ol><li><strong>File watcher</strong> -- The configuration file is polled every 5 seconds for changes</li><li><strong>File format</strong> -- Ensure the YAML file is valid (check for indentation errors)</li><li><strong>Section limitations</strong> -- Only rule changes are hot-reloaded. Changes to servers, auths, monitor, and webui sections require a restart</li></ol><h3 id="i-get-too-many-requests-errors-from-the-game-server" tabindex="-1">I get &quot;too many requests&quot; errors from the game server <a class="header-anchor" href="#i-get-too-many-requests-errors-from-the-game-server" aria-label="Permalink to &quot;I get &quot;too many requests&quot; errors from the game server&quot;">​</a></h3><ol><li><strong>Increase the interval</strong> -- Set <code>monitor.interval</code> to a higher value (e.g., 60 seconds)</li><li><strong>Increase jitter</strong> -- Add more jitter to make request timing less predictable</li><li><strong>Reduce servers</strong> -- Monitor fewer servers simultaneously</li></ol><h3 id="the-binary-is-flagged-by-antivirus-software" tabindex="-1">The binary is flagged by antivirus software <a class="header-anchor" href="#the-binary-is-flagged-by-antivirus-software" aria-label="Permalink to &quot;The binary is flagged by antivirus software&quot;">​</a></h3><p>The Go binary is compiled from source code. Some antivirus software may flag Go binaries due to their packaging. You can:</p><ol><li>Build from source yourself using <code>make build</code></li><li>Add an exclusion for the binary in your antivirus software</li><li>Verify the binary SHA256 checksum against a trusted build</li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="debug-mode" tabindex="-1">Debug Mode <a class="header-anchor" href="#debug-mode" aria-label="Permalink to &quot;Debug Mode&quot;">​</a></h3><p>Run the application with debug-level logging to get more detailed output:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Temporarily edit main.go to change log level:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">slog.LevelDebug</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or build a debug version:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -gcflags=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-N -l&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> autobuy-debug</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cmd/autobuy</span></span></code></pre></div><h3 id="session-issues" tabindex="-1">Session Issues <a class="header-anchor" href="#session-issues" aria-label="Permalink to &quot;Session Issues&quot;">​</a></h3><p>If you encounter persistent session problems:</p><ol><li>Stop the application</li><li>Delete the session file (<code>session.json</code> by default)</li><li>Restart the application</li><li>A fresh login will be performed</li></ol><h3 id="checking-the-market-url" tabindex="-1">Checking the Market URL <a class="header-anchor" href="#checking-the-market-url" aria-label="Permalink to &quot;Checking the Market URL&quot;">​</a></h3><p>The tool discovers the market URL automatically. To verify the discovery is working:</p><ol><li>Enable debug logging</li><li>Look for the line: <code>INFO discovered market URL url=...</code></li><li>If discovery fails, the tool falls back to a direct URL</li></ol><h3 id="validating-the-configuration" tabindex="-1">Validating the Configuration <a class="header-anchor" href="#validating-the-configuration" aria-label="Permalink to &quot;Validating the Configuration&quot;">​</a></h3><p>Use a YAML validator to check your configuration file for syntax errors:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Using Python</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import yaml; yaml.safe_load(open(&#39;configs/config.yaml&#39;))&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Using yq (if installed)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eval</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> configs/config.yaml</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/null</span></span></code></pre></div><h3 id="common-error-messages" tabindex="-1">Common Error Messages <a class="header-anchor" href="#common-error-messages" aria-label="Permalink to &quot;Common Error Messages&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Error</th><th>Likely Cause</th><th>Solution</th></tr></thead><tbody><tr><td><code>login failed</code></td><td>Invalid credentials or network issue</td><td>Verify username/password and server URL</td></tr><tr><td><code>failed to fetch market page</code></td><td>Network issue or expired session</td><td>Check connectivity; session will auto-renew</td></tr><tr><td><code>failed to parse HTML</code></td><td>Market page format changed</td><td>Report as a bug on GitHub</td></tr><tr><td><code>purchase returned status 404</code></td><td>Aircraft no longer available</td><td>The listing was removed or sold</td></tr><tr><td><code>bid failed: unexpected response</code></td><td>Auction format may have changed</td><td>Check the aircraft page manually</td></tr><tr><td><code>address ... is not allowed</code></td><td>URL validation blocked the request</td><td>Check server URL configuration</td></tr></tbody></table><h3 id="getting-help" tabindex="-1">Getting Help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting Help&quot;">​</a></h3><p>If you encounter issues not covered here:</p><ol><li><strong>Check the logs</strong> -- Look for error messages in the console output</li><li><strong>Search GitHub Issues</strong> -- Check if the problem has been reported at <a href="https://github.com/Maicarons/airlinesim-autobuy/issues" target="_blank" rel="noreferrer">github.com/Maicarons/airlinesim-autobuy/issues</a></li><li><strong>Open a new issue</strong> -- Provide the following information: <ul><li>Application version (commit hash or binary build date)</li><li>Configuration file (with sensitive fields redacted)</li><li>Log output from the session</li><li>Steps to reproduce the issue</li></ul></li></ol>`,68)])])}const g=i(n,[["render",o]]);export{p as __pageData,g as default};
